extends Node3D

@export_category("Tree Structure")
@export var num_main_branches := 5
@export var max_sub_branches := 4
@export var trunk_height := 5.0
@export var trunk_width := 1.5
@export var random_seed := 42

func _ready() -> void:
	seed(random_seed)  # deterministic chaos
	_create_materials()
	_build_trunk()
	_generate_branches_from(Vector3(0, trunk_height, 0), trunk_height * 0.7, 3)

func _build_trunk() -> void:
	var trunk = _make_box(trunk_width, trunk_height, trunk_width, trunk_material)
	trunk.position = Vector3(0, trunk_height * 0.5, 0)
	add_child(trunk)

func rebuild_tree() -> void:
	# Clear everything
	for child in get_children():
		if not child.owner:
			child.queue_free()
	await get_tree().process_frame

	# Regenerate from scratch
	seed(random_seed)
	_create_materials()
	_build_trunk()
	_generate_branches_from(
		Vector3(0, trunk_height, 0),
		trunk_height * 0.7,
		3
	)

func apply_grid_config(config: Dictionary) -> void:
	if config.has("num_main_branches"):
		num_main_branches = int(config["num_main_branches"])
	if config.has("random_seed"):
		random_seed = int(config["random_seed"])
	# ...
	rebuild_tree()
